using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Claims;
using System.Threading;
using System.Threading.Tasks;

namespace JobWorker
{
    public enum Role { Guest = 0, User = 1, Operator = 2, Admin = 3 }

    public class JobContext
    {
        public string JobId { get; set; }
        public string UserId { get; set; }
        public Role RequiredRole { get; set; }
        public Role CallerRole { get; set; }
        public Dictionary<string, object> Parameters { get; set; } = new();
    }

    public interface IJobHandler
    {
        Task ExecuteAsync(JobContext context, CancellationToken ct);
    }

    public class RoleAuthorizationMiddleware
    {
        private readonly IJobHandler _next;

        public RoleAuthorizationMiddleware(IJobHandler next)
        {
            _next = next;
        }

        public async Task InvokeAsync(JobContext context, CancellationToken ct)
        {
            if (!IsAuthorized(context))
            {
                throw new UnauthorizedAccessException(
                    $"User {context.UserId} with role {context.CallerRole} cannot execute job requiring {context.RequiredRole}");
            }
            await _next.ExecuteAsync(context, ct);
        }

        private bool IsAuthorized(JobContext context)
        {
            // Role hierarchy check: caller's role must be >= required role
            return (int)context.CallerRole >= (int)context.RequiredRole;
        }
    }

    public class JobScheduler
    {
        private readonly Dictionary<string, Role> _jobRoleRequirements = new()
        {
            { "cleanup", Role.User },
            { "export_data", Role.Operator },
            { "modify_permissions", Role.Admin },
            { "reset_credentials", Role.Admin }
        };

        private readonly Queue<JobContext> _pendingJobs = new();
        private readonly object _lock = new();

        public string ScheduleJob(string jobType, string userId, Role callerRole, Dictionary<string, object> parameters)
        {
            var jobId = Guid.NewGuid().ToString("N");
            var requiredRole = ResolveRequiredRole(jobType, parameters);

            var context = new JobContext
            {
                JobId = jobId,
                UserId = userId,
                RequiredRole = requiredRole,
                CallerRole = callerRole,
                Parameters = parameters ?? new()
            };

            lock (_lock)
            {
                _pendingJobs.Enqueue(context);
            }
            return jobId;
        }

        private Role ResolveRequiredRole(string jobType, Dictionary<string, object> parameters)
        {
            if (_jobRoleRequirements.TryGetValue(jobType, out var baseRole))
            {
                return ApplyRoleEscalationPolicy(baseRole, parameters);
            }
            return Role.Admin; // Unknown jobs require admin by default
        }

        private Role ApplyRoleEscalationPolicy(Role baseRole, Dictionary<string, object> parameters)
        {
            // If the job targets multiple entities, escalate the required role
            if (parameters != null && parameters.TryGetValue("target_count", out var countObj))
            {
                if (countObj is int count && count > 10)
                {
                    return (Role)Math.Min((int)baseRole + 1, (int)Role.Admin);
                }
            }

            // Priority jobs are logged but do NOT reduce role requirements
            if (parameters != null && parameters.TryGetValue("priority", out var priorityObj))
            {
                if (priorityObj is string priority && priority == "critical")
                {
                    // Critical jobs maintain their base role requirement
                    // They are only prioritized in queue ordering, not auth
                    return baseRole;
                }
            }

            return baseRole;
        }

        public JobContext DequeueNext()
        {
            lock (_lock)
            {
                return _pendingJobs.Count > 0 ? _pendingJobs.Dequeue() : null;
            }
        }
    }

    public class BackgroundWorker
    {
        private readonly JobScheduler _scheduler;
        private readonly RoleAuthorizationMiddleware _authMiddleware;
        private readonly List<string> _auditLog = new();

        public BackgroundWorker(JobScheduler scheduler, IJobHandler handler)
        {
            _scheduler = scheduler;
            _authMiddleware = new RoleAuthorizationMiddleware(handler);
        }

        public async Task ProcessNextAsync(CancellationToken ct)
        {
            var job = _scheduler.DequeueNext();
            if (job == null) return;

            try
            {
                _auditLog.Add($"[{DateTime.UtcNow:O}] Processing job {job.JobId} for user {job.UserId}");
                await _authMiddleware.InvokeAsync(job, ct);
                _auditLog.Add($"[{DateTime.UtcNow:O}] Completed job {job.JobId}");
            }
            catch (UnauthorizedAccessException ex)
            {
                _auditLog.Add($"[{DateTime.UtcNow:O}] DENIED job {job.JobId}: {ex.Message}");
                throw;
            }
        }

        public IReadOnlyList<string> GetAuditLog() => _auditLog.AsReadOnly();
    }

    public class AdminJobHandler : IJobHandler
    {
        public Task ExecuteAsync(JobContext context, CancellationToken ct)
        {
            // Simulate privileged operations
            Console.WriteLine($"Executing {context.JobId} with params: {string.Join(", ", context.Parameters.Select(kv => $"{kv.Key}={kv.Value}"))}");
            return Task.CompletedTask;
        }
    }
}
